import zipfile
import xml.etree.ElementTree as ET

MAIN = '{http://schemas.openxmlformats.org/spreadsheetml/2006/main}'
REL = '{http://schemas.openxmlformats.org/officeDocument/2006/relationships}'

def col_to_idx(ref):
    letters = ''.join(ch for ch in ref if ch.isalpha())
    idx = 0
    for ch in letters:
        idx = idx * 26 + (ord(ch.upper()) - ord('A') + 1)
    return idx - 1

def row_idx(ref):
    return int(''.join(ch for ch in ref if ch.isdigit())) - 1

z = zipfile.ZipFile('budget.xlsx')
names = z.namelist()
print("Archive entries:", names)

wb_xml = ET.fromstring(z.read('xl/workbook.xml'))
rels_xml = ET.fromstring(z.read('xl/_rels/workbook.xml.rels'))

rid_to_target = {}
for rel in rels_xml:
    rid_to_target[rel.get('Id')] = rel.get('Target')

shared = []
if 'xl/sharedStrings.xml' in names:
    sst = ET.fromstring(z.read('xl/sharedStrings.xml'))
    for si in sst.findall(f'{MAIN}si'):
        parts = [t.text or '' for t in si.iter(f'{MAIN}t')]
        shared.append(''.join(parts))

sheets = []
for s in wb_xml.find(f'{MAIN}sheets'):
    rid = s.get(f'{REL}id')
    target = rid_to_target.get(rid)
    if target and not target.startswith('xl/'):
        target = 'xl/' + target
    sheets.append((s.get('name'), target))

for sheet_name, target in sheets:
    print(f"\n=== Sheet: {sheet_name} ({target}) ===")
    ws = ET.fromstring(z.read(target))
    sheet_data = ws.find(f'{MAIN}sheetData')
    if sheet_data is None:
        print("(no sheetData)")
        continue
    for row in sheet_data.findall(f'{MAIN}row'):
        out = []
        for c in row.findall(f'{MAIN}c'):
            ref = c.get('r')
            t = c.get('t')
            v = c.find(f'{MAIN}v')
            is_el = c.find(f'{MAIN}is')
            if t == 's' and v is not None:
                val = shared[int(v.text)]
            elif t == 'inlineStr' and is_el is not None:
                val = ''.join(x.text or '' for x in is_el.iter(f'{MAIN}t'))
            elif v is not None:
                val = v.text
            else:
                val = None
            out.append((ref, val))
        if out:
            print(out)

